package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock()
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 10, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 10, 0, clk, true},
		{"negative rate", 10, -1, clk, true},
		{"valid", 10, 2.5, clk, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"zero n always allowed", 5, 1, 0, 0, true},
		{"negative n always allowed", 5, 1, 0, -3, true},
		{"full bucket allows capacity", 5, 1, 0, 5, true},
		{"over capacity never allowed", 5, 1, 0, 6, false},
		{"empty bucket denies", 5, 1, 0, 6, false},
		{"refill allows partial", 10, 2, 3 * time.Second, 5, true},
		{"refill insufficient", 10, 2, 1 * time.Second, 5, false},
		{"refill caps at capacity", 5, 10, time.Hour, 5, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clk := newFakeClock()
			b, err := New(tt.cap, tt.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			clk.Advance(tt.advance)
			if got := b.AllowN(tt.n); got != tt.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestAllowConsumesTokens(t *testing.T) {
	clk := newFakeClock()
	b, err := New(3, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(2) || !b.AllowN(1) {
		t.Fatal("expected first two calls to succeed")
	}
	if b.AllowN(1) {
		t.Fatal("expected bucket to be empty")
	}
	clk.Advance(2 * time.Second)
	if !b.AllowN(2) {
		t.Fatal("expected refill to allow 2 tokens")
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock()
	b, err := New(100, 1000, clk)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != 100 {
		t.Fatalf("allowed = %d, want 100", got)
	}
}
