		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 1, 0, clock, true},
		{"negative rate", 1, -1, clock, true},
		{"valid", 5, 2.5, clock, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := NewTokenBucket(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	b, err := NewTokenBucket(3, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	steps := []struct {
		advance time.Duration
		n       int
		want    bool
	}{
		{0, 3, true},
		{0, 1, false},
		{500 * time.Millisecond, 1, false},
		{500 * time.Millisecond, 1, true},
		{0, 3, false},
